class Defender : Actor() {
    init {
        val sprite = Image()
        sprite.scale(38, 24)
        sprite.setColor(80, 170, 255)
        sprite.fillRect(4, 8, 30, 12)
        sprite.fillRect(12, 2, 14, 8)
        sprite.setColor(220, 240, 255)
        sprite.fillRect(18, 0, 3, 8)
        setImage(sprite)
    }

    override fun act() {
        if (isKeyDown("left")) setLocation(x - 5, y)
        if (isKeyDown("right")) setLocation(x + 5, y)
    }
}

class Laser : Actor() {
    init {
        val sprite = Image()
        sprite.scale(4, 14)
        sprite.setColor(255, 230, 90)
        sprite.fillRect(0, 0, 4, 14)
        setImage(sprite)
    }

    override fun act() { setLocation(x, y - 8) }
}

class SpaceInvadersWorld : World(720, 480, 1) {
    private var direction = 1
    private var frame = 0
    private var shotCooldown = 0
    private val defender = Defender()

    init {
        setBackground(17, 24, 39)
        var row = 0
        while (row < 4) {
            var column = 0
            while (column < 8) {
                addObject(Invader(), 110 + column * 70, 80 + row * 42)
                column += 1
            }
            row += 1
        }
        addObject(defender, 360, 420)
        showText("Move with left/right. Press Space to fire.", 20, 25)
    }

    override fun act() {
        frame += 1
        if (shotCooldown > 0) shotCooldown -= 1
        if (isKeyDown("space") && shotCooldown == 0) {
            addObject(Laser(), defender.x, defender.y - 20)
            shotCooldown = 12
        }
        if (frame % 5 == 0) {
            val invaders = getObjects<Invader>()
            for (invader in invaders) invader.setLocation(invader.x + direction * 8, invader.y)
            if (invaders.isNotEmpty() && (invaders[0].x > width - 70 || invaders[0].x < 70)) direction = direction * -1
        }
        val lasers = getObjects<Laser>()
        val invaders = getObjects<Invader>()
        for (laser in lasers) {
            if (laser.y < 10) removeObject(laser)
            else for (invader in invaders) if (laser.isTouching(invader)) { removeObject(laser); removeObject(invader) }
        }
        if (getObjects<Invader>().isEmpty()) {
            showText("You win! Press Reset to play again.", 235, 245)
            stop()
        }
    }
}

fun main() {
    val spaceWorld = SpaceInvadersWorld()
    showWorld(spaceWorld)
}
